136	  "version": 1,
137	  "samples": {`+rawSampleS1TwoHandovers+`},
138	  "transfers": {
139	    "TR-001": {`+rawTR001Confirmed+`}
140	  },
141	  "transfers": {
142	    "TR-001": {`+second+`}
143	  }
144	}`)
145		mustRejectOpen(t, path, "TR-001", "出现多次")
146	}
147	
148	// TestOpenRejectsDuplicateAcrossFieldsSeparatedByTopLevelFields 两个同名
149	// transfers 字段之间隔着其他顶层字段、第二个字段内还隔着其他编号的交接，
150	// 重复编号同样不能漏过。
151	func TestOpenRejectsDuplicateAcrossFieldsSeparatedByTopLevelFields(t *testing.T) {
152		path := writeRawLedger(t, `{
153	  "version": 1,
154	  "transfers": {
155	    "TR-001": {`+rawTR001Confirmed+`}
156	  },
157	  "samples": {`+rawSampleS1TwoHandovers+`},
158	  "note": {"text": "两个交接集合之间隔着其他顶层字段"},
159	  "transfers": {
160	    "TR-002": {`+rawTR002Confirmed+`},
161	    "TR-001": {`+rawTR001Confirmed+`}
162	  }
163	}`)
164		mustRejectOpen(t, path, "TR-001", "出现多次")
165	}
166	
167	// TestOpenRejectsIdenticalDuplicateAcrossTwoFields 两个字段里的 TR-001
168	// 内容完全相同、确认状态相同也必须拒绝：不能按内容是否一致挑选其中一条。
169	func TestOpenRejectsIdenticalDuplicateAcrossTwoFields(t *testing.T) {
170		path := writeRawLedger(t, `{
171	  "version": 1,
172	  "samples": {`+rawSampleS1TwoHandovers+`},
173	  "transfers": {
174	    "TR-001": {`+rawTR001Confirmed+`}
175	  },
176	  "transfers": {
177	    "TR-001": {`+rawTR001Confirmed+`}
178	  }
179	}`)
180		mustRejectOpen(t, path, "TR-001", "出现多次")
181	}
182	
183	// TestOpenRejectsDuplicateAcrossFieldsViaUnicodeEscape 分处两个字段的编号
184	// 经 JSON 解码后是同一文字（其中一个首字符写成 U+0054 转义）时仍算重复。
185	func TestOpenRejectsDuplicateAcrossFieldsViaUnicodeEscape(t *testing.T) {
186		path := writeRawLedger(t, `{
187	  "version": 1,
188	  "samples": {`+rawSampleS1TwoHandovers+`},
189	  "transfers": {
190	    `+escapedTR001+`: {`+rawTR001Confirmed+`}
191	  },
192	  "transfers": {
193	    "TR-001": {`+rawTR001Confirmed+`}
194	  }
195	}`)
196		mustRejectOpen(t, path, "TR-001", "出现多次")
197	}
198	
199	// TestOpenDuplicateAcrossFieldsFailsWholeFile 跨字段重复时，即使文件里还
200	// 有完全正常的样品，也不能只载入正常部分：整份打开失败、原文件保持原样。
201	func TestOpenDuplicateAcrossFieldsFailsWholeFile(t *testing.T) {
202		path := writeRawLedger(t, `{
203	  "version": 1,
204	  "samples": {
205	    "OK": {"id":"OK","initial":100,"remaining":100,"holder":"h","location":"l","children":[],"history":[]},
206	    "S1": {"id":"S1","initial":10000,"remaining":6750,"holder":"王五","location":"C","children":[],"history":[]}
207	  },
208	  "transfers": {
209	    "TR-001": {`+rawTR001Confirmed+`}
210	  },
211	  "transfers": {
212	    "TR-001": {`+rawTR001Confirmed+`}
213	  }
214	}`)
215		mustRejectOpen(t, path, "TR-001", "出现多次")
216	}
217	
218	// TestOpenMergesDistinctIDsAcrossDuplicateTransfersFields 多个同名 transfers
219	// 字段分别只含不同编号时，不应仅因字段重名就报编号冲突：各条记录合并恢复，
220	// 仍能按编号查询到各自的确认信息，样品多次转手的现状也正常恢复。
221	func TestOpenMergesDistinctIDsAcrossDuplicateTransfersFields(t *testing.T) {
222		path := writeRawLedger(t, `{
223	  "version": 1,
224	  "samples": {`+rawSampleS1TwoHandovers+`},
225	  "transfers": {
226	    "TR-001": {`+rawTR001Confirmed+`}
227	  },
228	  "transfers": {
229	    "TR-002": {`+rawTR002Confirmed+`}
230	  }
231	}`)
232		s, err := Open(path)
233		if err != nil {
234			t.Fatalf("字段重名但编号互不相同应正常打开: %v", err)
235		}
236		for _, id := range []string{"TR-001", "TR-002"} {
237			tr, err := s.GetTransfer(id)
238			if err != nil {
239				t.Fatalf("交接 %s 应跨字段合并恢复并可查询: %v", id, err)
240			}
241			if !tr.Confirmed {
242				t.Fatalf("交接 %s 应为已确认记录: %+v", id, tr)
243			}
244		}
245		if len(s.data.Transfers) != 2 {
246			t.Fatalf("两个字段中的不同编号都应保留, got %d 条", len(s.data.Transfers))
247		}
248		p, err := s.GetSample("S1")
249		if err != nil {
250			t.Fatal(err)
251		}
252		if p.Remaining != "6.750" || p.Holder != "王五" || p.Location != "C" {
253			t.Fatalf("同一样品不同编号的两次转手应各自保留: %+v", p)
254		}
255	}
256	
257	// TestOpenMergesDistinctIDsAcrossFieldsWithNullBetween 后一个 transfers
258	// 字段为 null 不应清空前一个字段已经保存的交接；中间插入的其他顶层字段
259	// 也不影响合并恢复。
260	func TestOpenMergesDistinctIDsAcrossFieldsWithNullBetween(t *testing.T) {
261		path := writeRawLedger(t, `{
262	  "version": 1,
263	  "samples": {`+rawSampleS1TwoHandovers+`},
264	  "transfers": {
265	    "TR-001": {`+rawTR001Confirmed+`},
266	    "TR-002": {`+rawTR002Confirmed+`}
267	  },
268	  "note": "中间字段",
269	  "transfers": null
270	}`)
271		s, err := Open(path)
272		if err != nil {
273			t.Fatalf("后一个 transfers 为 null 不应影响前一个字段的记录: %v", err)
274		}
275		if len(s.data.Transfers) != 2 {
276			t.Fatalf("前一个字段的两条交接都应保留, got %d 条", len(s.data.Transfers))
277		}
278	}
279	
280	// TestOpenDoesNotMentionTransferIDInTextAsDuplicate 编号文字只出现在保管
281	// 历史说明或交接记录字段值（含 Unicode 转义写法、含未知字段）中，而键
282	// 各自不同，不能误报为重复。同一样品的两次转手按现有规则正常恢复。
283	func TestOpenDoesNotMentionTransferIDInTextAsDuplicate(t *testing.T) {
284		path := writeRawLedger(t, `{
285	  "version": 1,
286	  "samples": {`+rawSampleS1TwoHandovers+`},
287	  "transfers": {
288	    "TR-001": {`+rawTR001Confirmed+`},
289	    "TR-002": {`+rawTR002Confirmed+`,"note":"参见 TR-001（转义写法 `+escapedTR001InText+`），仅为说明文字"}
290	  }
291	}`)
292		s, err := Open(path)
293		if err != nil {
294			t.Fatalf("编号仅在说明文字中出现不应判为重复，文件应正常打开: %v", err)
295		}
296		for _, id := range []string{"TR-001", "TR-002"} {
297			tr, err := s.GetTransfer(id)
298			if err != nil {
299				t.Fatalf("交接 %s 应按现有规则恢复: %v", id, err)
300			}
301			if !tr.Confirmed {
302				t.Fatalf("交接 %s 应为已确认记录: %+v", id, tr)
303			}
304		}
305		p, err := s.GetSample("S1")
306		if err != nil {
307			t.Fatal(err)
308		}
309		if p.Remaining != "6.750" || p.Holder != "王五" || p.Location != "C" {
310			t.Fatalf("样品多次转手后的当前状态应正常恢复: %+v", p)
311		}
312	}
313	
314	// TestHandoverResubmitStillIdempotentWithReopen 调用交接功能重复提交同一
315	// 请求，仍按原规则幂等返回原记录；落盘文件只有一条该编号的交接，重新
316	// 打开也不会被新的唯一性检查误伤。
317	func TestHandoverResubmitStillIdempotentWithReopen(t *testing.T) {
318		s, hAt1, rAt1, _, _ := setupDivergedHandover(t)
319	
320		again, err := s.Handover(HandoverInput{
321			TransferID: "TR-001", SampleID: "S-001",
322			FromHolder: "张三", FromLocation: "实验室A",
323			ToHolder: "李四", ToLocation: "实验室B", HandedOverAt: hAt1,
324		})
325		if err != nil {
326			t.Fatalf("重复提交同一交接请求应返回原记录: %v", err)
327		}
328		requireOldFirstTransfer(t, again, hAt1, rAt1)
329		if len(s.data.Transfers) != 2 {
330			t.Fatalf("幂等提交不得新增交接, got %d 条", len(s.data.Transfers))
331		}
332	
333		s2, err := Open(s.path)
334		if err != nil {
335			t.Fatalf("正常保存的文件重新打开不应受影响: %v", err)
336		}
337		old, err := s2.GetTransfer("TR-001")
338		if err != nil {
339			t.Fatal(err)
340		}
341		requireOldFirstTransfer(t, old, hAt1, rAt1)
342	}
343	
344	// TestOpenDuplicateTransferErrorIsInvalid 单独固定错误分类：重复编号错误
345	// 必须能被 errors.Is 判定为 ErrInvalid（而非解码错误或冲突类）。
346	func TestOpenDuplicateTransferErrorIsInvalid(t *testing.T) {
347		path := writeRawLedger(t, `{
348	  "version": 1,
349	  "samples": {`+rawSampleS1TwoHandovers+`},
350	  "transfers": {
351	    "TR-001": {`+rawTR001Confirmed+`},
352	    "TR-001": {`+rawTR001Confirmed+`}
353	  }
354	}`)
355		s, err := Open(path)
356		if s != nil {
357			t.Fatalf("打开失败必须返回 nil Store")
358		}
359		if !errors.Is(err, ErrInvalid) {
360			t.Fatalf("重复交接编号应判定为 ErrInvalid, got %v", err)
361		}
362		if errors.Is(err, ErrConflict) {
363			t.Fatalf("重复交接编号不应归类为 ErrConflict: %v", err)
364		}
365	}
